using UnityEngine;

public class WindWall : MonoBehaviour
{
	public NegateProjectiles negateProjectiles;

	public Attack attack;

	private float lifeTime = 3f;

	private ChaosQuickStopwatch lifeTimeStopwatch;

	private static GameObject _prefab;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/WindWall.prefab");
			}
			return _prefab;
		}
	}

	private void Start()
	{
		lifeTimeStopwatch = new ChaosQuickStopwatch(lifeTime);
		lifeTimeStopwatch.IsRunning = true;
	}

	private void Update()
	{
		if (!lifeTimeStopwatch.IsRunning)
		{
			Object.Destroy(gameObject);
		}
	}
}
using UnityEngine;

public class WindWard : Ward
{
	private static GameObject prefab;

	public ParticleSystem particleEffect;

	private ParticleSystem windPartSys;

	private ParticleSystemOverride sizeOverride;

	private bool isFirstAtk = true;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/WindWard.prefab"));

	public override void Awake()
	{
		base.Awake();
		element = ElementType.Air;
		windPartSys = transform.Find("LinePartSys").GetComponent<ParticleSystem>();
	}

	public override void Start()
	{
		base.Start();
		if (isEmpowered)
		{
			ParticleSystem.ShapeModule shape = windPartSys.shape;
			shape.radius = attackCollider.radius;
			sizeOverride = ParticleEffectOverrides.StartSize10;
		}
		else
		{
			sizeOverride = ParticleEffectOverrides.StartSize8;
		}
		Vector3 givenPosition = spawnPosition;
		float radius = attackCollider.radius;
		WindBurst.CreateBurst(givenPosition, string.Empty, string.Empty, 1, radius).emitParticles = false;
		PoolManager.GetPoolItem<ParticleEffect>("WindTwirlEffect").Emit(1, spawnPosition);
		PoolManager.GetPoolItem<ParticleEffect>("AirSpinnerBurst").Emit(1, spawnPosition, sizeOverride);
		ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("AirVortex");
		int? particleCount = 1;
		Vector3? position = spawnPosition;
		Vector3? localEulerAngles = new Vector3(0f, 0f, Random.Range(0f, 360f));
		poolItem.Emit(particleCount, position, null, localEulerAngles);
		DustEmitter poolItem2 = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount2 = 150;
		radius = 2f;
		float startSpeed = -8f;
		localEulerAngles = spawnPosition;
		poolItem2.EmitCircle(particleCount2, radius, startSpeed, -1f, localEulerAngles);
		SoundManager.PlayWithDistAndSPR("WindCircle", spawnPosition);
		SoundManager.PlayWithDistAndSPR("StandardHeavySwing", spawnPosition);
	}

	public override void OnPulseActivate()
	{
		if (isFirstAtk)
		{
			isFirstAtk = false;
			return;
		}
		base.OnPulseActivate();
		PoolManager.GetPoolItem<ParticleEffect>("AirSpinnerBurst").Emit(1, spawnPosition, sizeOverride);
		SoundManager.PlayWithDistAndSPR("WindCircle", spawnPosition);
	}

	public override void DestroyWard()
	{
		if (particleEffect != null)
		{
			particleEffect.Stop();
		}
		base.DestroyWard();
		PoolManager.GetPoolItem<ParticleEffect>("SpinningAirBurst").Emit(1, spawnPosition, ParticleEffectOverrides.FlipX);
		string audioID = "TornadoEnd";
		Vector2? soundOrigin = spawnPosition;
		float overridePitch = Random.Range(0.8f, 0.9f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
	}
}

