	private bool isDead;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/AttackOrb.prefab"));

	private void Awake()
	{
		rigidbody2D = GetComponent<Rigidbody2D>();
		attack = transform.Find("Attack").GetComponent<Attack>();
		movement = GetComponent<Movement>();
	}

	private void Start()
	{
		if (orbitTrans != null)
		{
			movement.InitOrbitAngle((orbitTrans.position - transform.position).normalized);
		}
	}

	private void Update()
	{
		if (!isDead)
		{
			movement.orbit = allowOrbit;
			if (orbitTrans == null)
			{
				DestroyAttackOrb();
			}
			else
			{
				movement.OrbitTarget(orbitTrans.position);
			}
		}
	}

	public void DestroyAttackOrb()
	{
		isDead = true;
		Object.Destroy(gameObject);
	}
